.toolbar .ns {
  position: relative;
  /* Border box of the menu, and of the name on the button before the filter. */
  --ns-cap: 340px;
}
.toolbar .ns .current {
  display: inline-flex;
  align-items: center;
  min-width: 128px;
  height: var(--control);
  text-align: left;
  font-family: var(--mono);
  font-size: var(--fs-sm);
  border: 1px solid var(--border);
  padding: 0 var(--sp2);
}
/* The cap is the button's border box. The filter sits outside it, so typing can
   widen the button without pushing the name out of the way. min-width: 0 lets
   the name ellipsize inside a flex button. */
.toolbar .ns .ns-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: calc(var(--ns-cap) - 2 * var(--sp2) - 2px);
}
.toolbar .ns .ns-prefix {
  flex: none;
  white-space: pre;
}
.ns-menu {
  position: fixed;
  z-index: 1000;
  max-width: var(--ns-cap);
  max-height: 240px;
  overflow-x: hidden;
  overflow-y: auto;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: var(--sp2);
