import { useState } from "react";
import { createRoot } from "react-dom/client";
import { NamespaceSelect } from "../src/screens";
import type { Kubi } from "../src/useKubi";

const LONG = "n".repeat(63);

function Harness() {
  const [namespace, setNamespace] = useState<string | null>("grafana");
  const [namespaces, setNamespaces] = useState(["a", "grafana", "kube-system", LONG]);
  const kubi = {
    activeTab: { namespace },
    namespaces,
    setNamespace,
  } as unknown as Kubi;
  return (
    <div>
      <div className="toolbar" id="bar" style={{ width: 880 }}>
        <NamespaceSelect kubi={kubi} />
      </div>
      <button id="use-long" onClick={() => setNamespace(LONG)}>
        use long
      </button>
      <button id="use-short" onClick={() => setNamespace("a")}>
        use short
      </button>
      <pre id="out" />
    </div>
  );
}

createRoot(document.getElementById("root")!).render(<Harness />);

