    button: Math.round(current.getBoundingClientRect().width * 10) / 10,
    items: buttons.map(b => b.textContent),
    widths: buttons.map(b => Math.round(b.getBoundingClientRect().width)),
    prefix: prefix ? prefix.textContent : null,
  };
})()

(() => {
  const current = document.querySelector('.ns .current');
  const name = document.querySelector('.ns-name');
  const prefix = document.querySelector('.ns-prefix');
  const menu = document.querySelector('.ns-menu:not(.ns-probe)');
  return {
    button: Math.round(current.getBoundingClientRect().width),
    menu: menu ? Math.round(menu.getBoundingClientRect().width) : null,
    name: name.textContent,
    nameClipped: name.scrollWidth > name.clientWidth + 1,
    prefix: prefix ? prefix.textContent : null,
    prefixClipped: prefix ? prefix.scrollWidth > prefix.clientWidth + 1 : null,
    empty: menu && menu.querySelector('.muted') ? menu.querySelector('.muted').textContent : null,
  };
})()

(() => {
