(() => {
  const button = document.querySelector('.ns .current');
  button.click();
  const menu = document.querySelector('.ns-menu:not(.ns-probe)');
  const br = button.getBoundingClientRect();
  const mr = menu ? menu.getBoundingClientRect() : null;
  return {
    buttonTop: Math.round(br.top),
