  };
})()

(async () => {
  const button = document.querySelector('.ns .current');
  button.click();
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  const menu = document.querySelector('.ns-menu:not(.ns-probe)');
  const br = button.getBoundingClientRect();
  const mr = menu ? menu.getBoundingClientRect() : null;
  return {
    buttonTop: Math.round(br.top),
    buttonBottom: Math.round(br.bottom),
    menuTop: mr ? Math.round(mr.top) : null,
    menuBottom: mr ? Math.round(mr.bottom) : null,
    above: mr ? mr.bottom <= br.top + 4 : null,
    open: !!menu,
  };
})()

(() => {
  const b = document.querySelector('.ns .current');
  let native = false;
  const mark = () => { native = true; };
  b.addEventListener('click', mark);
  b.click();
  b.removeEventListener('click', mark);
  return { native, html: document.querySelector('.ns').innerText.slice(0, 200) };
})()

(async () => {
  const errors = [];
  const orig = console.error;
  console.error = (...args) => { errors.push(args.map(a => String(a && a.message || a)).join(' | ')); orig.apply(console, args); };
  window.addEventListener('error', (e) => errors.push('window ' + e.message));
  document.querySelector('.ns .current').click();
  await new Promise(r => setTimeout(r, 50));
  console.error = orig;
  return { errors, menus: document.querySelectorAll('.ns-menu').length, text: document.querySelector('.ns').innerText.slice(0, 300) };
})()

(() => {
  const buttons = [...document.querySelectorAll('.ns-menu:not(.ns-probe) button')];
  return buttons.map(b => ({
    text: b.textContent,
    bg: getComputedStyle(b).backgroundColor,
    w: Math.round(b.getBoundingClientRect().width),
    on: b.classList.contains('on'),
  }));
})()

(() => {
  const probe = document.querySelector('.ns-probe button');
  const prev = probe.textContent;
  probe.textContent = 'All namespaces';
  const visible = [...document.querySelectorAll('.ns-menu:not(.ns-probe) button')][0];
  const menu = document.querySelector('.ns-menu:not(.ns-probe)');
  const info = {
    probeW: probe.offsetWidth,
    probeScroll: probe.scrollWidth,
    probeClient: probe.clientWidth,
    visibleW: visible.offsetWidth,
    visibleScroll: visible.scrollWidth,
    visibleClient: visible.clientWidth,
    menuW: menu.offsetWidth,
    menuClient: menu.clientWidth,
    probePad: getComputedStyle(probe).padding,
    visiblePad: getComputedStyle(visible).padding,
    probeFont: getComputedStyle(probe).font,
    visibleFont: getComputedStyle(visible).font,
    probeBorder: getComputedStyle(probe).border,
    visibleBorder: getComputedStyle(visible).border,
  };
  probe.textContent = prev;
  return info;
})()
